opts={"A":"AFK","B":"LQV","C":"PTX","D":"DIN"}
g={k:(ord(v[1])-ord(v[0]),ord(v[2])-ord(v[1])) for k,v in opts.items()}
odd=[k for k in g if list(g.values()).count(g[k])==1]
assert odd==["C"]
assert opts["C"]=="PTX" and "A" not in odd and "B" not in odd and "D" not in odd

# antonym pairs table (semantic rule)
ant={"blossom":"wither","stagnate":"flow"}
opts={"A":"stand","B":"rest","C":"flow","D":"languish"}
m=[k for k,v in opts.items() if v==ant["stagnate"]]
assert m==["C"]
assert opts["C"]=="flow" and opts["A"]!="flow" and opts["B"]!="flow" and opts["D"]!="flow"

s1={"sit","on","chair"};c1={"sk","mi","cn"}
s2={"the","chair","broke"};c2={"gm","fr","mi"}
common=c1&c2
assert common=={"mi"} and (s1&s2)=={"chair"}
opts={"A":"gm","B":"sk","C":"mi","D":"cn"}
assert opts["C"] in common
assert opts["A"] not in common and opts["B"] not in common and opts["D"] not in common

opts={"A":(2,2,4),"B":(1,3,3),"C":(2,4,8),"D":(3,2,5)}
p={k:v[0]*v[1]==v[2] for k,v in opts.items()}
odd=[k for k,v in p.items() if not v]
assert odd==["D"]
assert p["A"] and p["B"] and p["C"] and not p["D"]

def ev(e): return eval(e)
base=["18","-","23","*","455","/","7","+","28"]
def sw(a,b):
    t=["18","-","23","*","455","/","7","+","28"]
    t=[b if x==a else a if x==b else x for x in t]
    return abs(eval("".join(t))-377)<1e-9
opts={"A":("/","-"),"B":("-","+"),"C":("+","*"),"D":("-","*")}
m=[k for k,v in opts.items() if sw(*v)]
assert m==["D"]
assert not sw(*opts["A"]) and not sw(*opts["B"]) and not sw(*opts["C"])

# L is female sibling of R; Q father of L => Q father of R
rel={"father_of_L":True,"L_sibling_R":True}
ans="Father" if rel["father_of_L"] and rel["L_sibling_R"] else None
opts={"A":"Sister","B":"Mother","C":"Father","D":"Wife"}
assert opts["C"]==ans
assert opts["A"]!=ans and opts["B"]!=ans and opts["D"]!=ans

def nxt(w):
    return "".join(chr(ord(c)-d) for c,d in zip(w,[4,3,2,1]))
seq=["ZVRN","VSPM","RPNL"]
for a,b in zip(seq,seq[1:]): assert nxt(a)==b
t=nxt("RPNL")
assert nxt(t)=="JJJJ"
opts={"A":"RNLL","B":"NMLK","C":"RMLN","D":"RNLK"}
assert opts["B"]==t
assert opts["A"]!=t and opts["C"]!=t and opts["D"]!=t

